98	\textbf{Window size $h$} & \textbf{OOD Success (\%)} \\
99	\midrule
100	$h = 2$  & 0 \\
101	$h = 5$  & 0 \\
102	$h = 10$ & 6.25 \\
103	$h = 20$ & 15.6 \\
104	$h = \text{full}$ (episode-level) & 23.88 \\
